Aquí te proporciono el código para la función que toma una referencia a un `std::string` que contiene texto con formato Markdown y devuelve otro `std::string` que contiene texto con formato HTML:

```cpp
#include <iostream>
#include <string>
#include <unordered_map>
#include <regex>

// Función para convertir texto con formato Markdown a HTML
std::string convertMarkdownToHTML(const std::string& markdown) {
    // Crear una tabla de símbolos para los tokens de Markdown
    std::unordered_map<std::string, std::string> markdown_to_html {
        {"#", "<h1>"},
        {"##", "<h2>"},
        {"###", "<h3>"},
        {"####", "<h4>"},
        {"#####", "<h5>"},
        {"######", "<h6>"},
        {"*", "<em>"},
        {"**", "<strong>"},
        {"`", "<code>"},
        {"[", "<a href='"],
        {"]", "'></a>"},
        {"(", "<span class='math'>"),
        {")", "</span>"},
        {"\\", "&#92;"},
        {"\\\\", "<br>"},
        {"---", "<hr>"},
        {"**\\*\\* ", "<b>"},
        {"\\*\\* ", "</b>"}
    };

    // Crear una expresión regular para encontrar los tokens de Markdown
    std::regex markdown_regex(R"((?:#|##|###|####|#####|######|[*]{1,2}|`|[(]{1,}[^\n]*[)]|[(]{1,}\s[^\n]*[)]|\(|\)|\\\\|---))", std::regex::extended);

    // Crear una cadena vacía para almacenar el texto HTML
    std::string html;

    // Recorrer la cadena de texto con formato Markdown
    std::string::const_iterator it = markdown.begin();
    std::string::const_iterator end = markdown.end();
    while (it != end) {
        // Buscar el siguiente token de Markdown
        std::string token = std::regex_search(it, end, markdown_regex);

        // Si no se encontró un token, agregar el resto de la cadena como texto plano
        if (token.empty()) {
            html += std::string(it, end);
            break;
        }

        // Agregar el símbolo HTML correspondiente al token de Markdown
        html += markdown_to_html[token];

        // Avanzar al siguiente token de Markdown
        it += token.length();
    }

    return html;
}

int main() {
    // Ejemplo de uso de la función
    std::string markdown = "# H1\n## H2\n### H3\n\n*Texto en cursiva*\n**Texto en negrita**\n`Código`\n[Enlace](https://example.com)\n(Expresión matemática)\n---\n\\*Caracter especial\\*\n**\\*Texto con asteriscos\\**";
    std::string html = convertMarkdownToHTML(markdown);
    std::cout << "Markdown:\n" << markdown << "\n\nHTML:\n" << html << std::endl;

    return 0;
}
```

Este código utiliza una tabla de símbolos para convertir los tokens de Markdown a HTML. También utiliza una expresión regular para encontrar los tokens de Markdown en la cadena de entrada. El resultado es un nuevo string con formato HTML. 

En el ejemplo de uso del código, se proporciona una cadena de texto con formato Markdown y se imprime el resultado convertido a HTML. 

